function drawArt(){if(!state.art)return;const w=canvas.width,h=canvas.height,im=state.art,s=scale(),iw=im.naturalWidth||im.width,ih=im.naturalHeight||im.height;const base=Math.max(w/iw,h/ih),k=base*state.artZoom,dw=iw*k,dh=ih*k,x=(w-dw)/2+state.artX*s,y=(h-dh)/2+state.artY*s;ctx.drawImage(im,x,y,dw,dh);}
