function fittedNameFont(text,maxWidth,maxPx,minPx){let px=maxPx;while(px>minPx){ctx.font=`italic 1000 ${px*scale()}px "Arial Black", Impact, sans-serif`;if(ctx.measureText(text).width<=maxWidth)break;px-=2;}return px;}
function fittedMetaFont(text,maxWidth,maxPx=22,minPx=14){let px=maxPx;while(px>minPx){ctx.font=`900 ${px*scale()}px "Arial Black", Impact, sans-serif`;if(ctx.measureText(text).width<=maxWidth)break;px-=1;}return px;}
function moveRequirementText(card){if(card?.kind!=="move")return "";return Object.entries(card.requirements||{}).filter(([,amount])=>Number(amount)>0).map(([method,amount])=>`◆ ${Number(amount)} ${String(method).toUpperCase()}`).join("   •   ");}
function drawBottomIdentity(){const card=currentCard();if(!card)return;const set=currentSet(),w=canvas.width,h=canvas.height,s=scale(),text=card.name.toUpperCase(),isMove=card.kind==="move";const fade=ctx.createLinearGradient(0,h*.66,0,h);fade.addColorStop(0,"rgba(0,0,0,0)");fade.addColorStop(.42,"rgba(0,0,0,.20)");fade.addColorStop(1,"rgba(0,0,0,.88)");ctx.fillStyle=fade;ctx.fillRect(0,h*.65,w,h*.35);ctx.save();ctx.textAlign="center";ctx.textBaseline="alphabetic";const nameY=card.kind==="superstar"?h*.94:isMove?h*.875:h*.905;fittedNameFont(text,w*.86,card.kind==="superstar"?66:isMove?58:61,29);ctx.lineJoin="round";ctx.lineWidth=7*s;ctx.strokeStyle=set.stroke;ctx.shadowColor="rgba(0,0,0,.95)";ctx.shadowBlur=13*s;ctx.shadowOffsetY=6*s;ctx.strokeText(text,w*.5,nameY);const g=ctx.createLinearGradient(0,h*.82,0,h*.94);g.addColorStop(0,set.nameTop);g.addColorStop(.58,set.nameTop);g.addColorStop(1,set.nameBottom);ctx.fillStyle=g;ctx.shadowColor=set.glow;ctx.shadowBlur=8*s;ctx.shadowOffsetY=0;ctx.fillText(text,w*.5,nameY);ctx.shadowColor="transparent";if(card.kind!=="superstar"){ctx.fillStyle="rgba(255,255,255,.90)";ctx.textBaseline="middle";let sub=KIND_LABELS[card.kind]||card.kind.toUpperCase();if(isMove){sub=`COST  ${card.cost??0}     •     DAM  ${card.damage??0}`;ctx.font=`900 ${23*s}px "Arial Black", Impact, sans-serif`;ctx.fillText(sub,w*.5,h*.925);const requirement=moveRequirementText(card);fittedMetaFont(requirement,w*.86,20,13);ctx.fillStyle=requirement?set.nameTop:"rgba(255,255,255,0)";ctx.fillText(requirement,w*.5,h*.965);}else{if(card.kind==="momentum")sub=`MOMENTUM     •     +${card.amount??1} ${String(card.method||"").toUpperCase()}`;ctx.font=`900 ${24*s}px "Arial Black", Impact, sans-serif`;ctx.fillText(sub,w*.5,h*.953);}}ctx.restore();}
