function updateOutputs(){$("#art-zoom-value").textContent=`${Math.round(state.artZoom*100)}%`;$("#art-x-value").textContent=Math.round(state.artX);$("#art-y-value").textContent=Math.round(state.artY);$("#quality-value").textContent=`${$("#quality").value}%`;}
