function updateSummary(){const card=currentCard(),path=destinationFor(card);$("#destination-path").textContent=path;$("#install-path").textContent=path;if(!card)return;$("#card-code").textContent=card.cardCode;$("#card-summary-name").textContent=card.name;$("#card-summary-kind").textContent=KIND_LABELS[card.kind]||card.kind.toUpperCase();$("#card-summary-stats").textContent=card.kind==="move"?`COST ${card.cost??0} · DAM ${card.damage??0}${moveRequirementText(card)?` · ${moveRequirementText(card).replaceAll("◆ ","")}`:""}`:card.kind==="momentum"?`+${card.amount??1} ${String(card.method||"").toUpperCase()} MOMENTUM`:"FRONT ART + NAME";$("#preview-card").textContent=`${card.cardCode} · ${card.name}`;$("#preview-label").textContent=currentSet().label;draw();}
function refreshSuperstarFilter(){const set=$("#set-select").value,sel=$("#superstar-select"),previous=sel.value;const stars=STUDIO_SUPERSTARS.filter(s=>set==="all"||s.setId===set);sel.innerHTML=`<option value="all">All Superstars</option>${stars.map(s=>`<option value="${s.id}">${s.name}</option>`).join("")}`;sel.value=stars.some(s=>s.id===previous)?previous:"all";}
function refreshCardList(){const set=$("#set-select").value,kind=$("#type-select").value,star=$("#superstar-select").value,focus=$("#superstar-focus").value,q=$("#card-search").value.trim().toLowerCase(),previous=$("#card-select").value;const cards=STUDIO_CARDS.filter(c=>{if(set!=="all"&&c.setId!==set)return false;if(kind!=="all"&&c.kind!==kind)return false;if(star!=="all"){const ids=focus==="deck"?c.deckSuperstarIds:c.specificSuperstarIds;if(!ids?.includes(star))return false;}if(q&&!`${c.name} ${c.cardCode} ${KIND_LABELS[c.kind]||c.kind}`.toLowerCase().includes(q))return false;return true;});const sel=$("#card-select");sel.innerHTML=cards.map(c=>`<option value="${c.id}">${c.cardCode} · ${c.name} · ${KIND_LABELS[c.kind]||c.kind.toUpperCase()}${c.kind==="move"?` · C${c.cost??0}/D${c.damage??0}`:""}</option>`).join("");if(!cards.length){sel.innerHTML='<option value="">No matching cards</option>';sel.disabled=true;updateSummary();return;}sel.disabled=false;sel.value=cards.some(c=>c.id===previous)?previous:cards[0].id;prepareSelectedCard();}
function prepareSelectedCard(){updateSummary();resetLayout();if(document.location.protocol==="file:"){state.art=null;state.artIsProjectAsset=false;resetCanvasSurface();draw();status("Choose your artwork with the file picker. Local-file WebP export is ready.",true);return;}useCurrentArt();}
async function useCurrentArt(){const card=currentCard();if(!card?.currentArt)return status("No current artwork is available for this card.",false);try{state.art=await loadImage(assetUrl(card.currentArt));state.artIsProjectAsset=true;resetLayout();status(document.location.protocol==="file:"?"Loaded current game art. Choose your own image with the file picker before local-file export.":"Loaded current game art.",true);}catch{status("Could not load the current game artwork.",false);}}
