async function urlToImage(rawUrl){
  const value=String(rawUrl||"").trim();
  if(!value){urlStatus("Paste a direct image URL first.",false);return status("Paste a direct image URL first.",false);}
  let url;
  try{url=new URL(value);if(!/^https?:$/.test(url.protocol))throw new Error("Only http:// and https:// image URLs are supported.");}
  catch(error){const message=`That is not a valid image URL: ${error?.message||error}`;urlStatus(message,false);return status(message,false);}
  const button=$("#load-art-url"),originalLabel=button?.textContent||"Load URL Artwork";
  if(button){button.disabled=true;button.textContent="Loading…";}
  urlStatus("Trying the image URL…");status("Trying the image URL…");
  try{
    try{
      const blob=await fetchImageBlob(url,false);
      await installUrlBlob(blob,false);
    }catch(directError){
      urlStatus("The source blocked direct browser access. Retrying automatically through the image proxy…");
      status("Direct URL access was blocked; retrying through the image proxy…");
      try{
        const blob=await fetchImageBlob(url,true);
        await installUrlBlob(blob,true);
      }catch(proxyError){
        const directText=directError?.message||String(directError),proxyText=proxyError?.message||String(proxyError);
        throw new Error(`Direct load failed (${directText}) and proxy retry failed (${proxyText}).`);
      }
    }
  }catch(error){
    const message=`Could not load URL artwork: ${error?.message||error}`;
    urlStatus(message,false);status(message,false);
  }finally{if(button){button.disabled=false;button.textContent=originalLabel;}}
}
function canvasToWebp(quality){return new Promise((resolve,reject)=>{if(typeof canvas.toBlob!=="function")return reject(new Error("This browser does not support canvas export."));try{canvas.toBlob(blob=>{if(!blob)return reject(new Error("The browser could not create an image file."));if(blob.type!=="image/webp")return reject(new Error("This browser did not encode WebP. Use current Chrome, Edge or Safari."));resolve(blob);},"image/webp",quality);}catch(error){reject(error);}});}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);}
async function exportWebp(){const card=currentCard();if(!card)return status("Choose a card before exporting.",false);if(!state.art)return status("Choose or load artwork before exporting.",false);if(document.location.protocol==="file:"&&state.artIsProjectAsset)return status("Your browser blocks exporting built-in project artwork from a local file. Choose your artwork with the file picker first.",false);draw();if(!canvasIsOriginClean()&&!state.artIsProjectAsset){resetCanvasSurface();draw();}if(!canvasIsOriginClean())return status("This preview contains a browser-blocked local asset. Choose the image with the file picker again.",false);status("Encoding finished card as WebP…");try{const blob=await canvasToWebp(Number($("#quality").value)/100),id=exportId(card);download(blob,`${id}.webp`);status(`Downloaded ${id}.webp. Put it at ${destinationFor(card)} and reload WWE Legacy. The finished front will be used automatically.`,true);}catch(error){status(`Export failed: ${error?.message||error}`,false);}}
function pointerDistance(){const pts=[...state.pointerMap.values()];return pts.length<2?null:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y);}
function onPointerDown(e){if(!state.art)return;canvas.setPointerCapture?.(e.pointerId);state.pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});if(state.pointerMap.size===1){state.dragPointerId=e.pointerId;state.dragLast={x:e.clientX,y:e.clientY};}else if(state.pointerMap.size===2){state.lastPinchDistance=pointerDistance();state.dragPointerId=null;state.dragLast=null;}}
